COL = {'亞洲': '#fcd34d', '歐洲': '#93c5fd', '非洲': '#fca5a5', '北美洲': '#86efac', '南美洲': '#c4b5fd', '大洋洲': '#f9a8d4', '南極洲': '#f1f5f9', '水': '#dbeafe'}
PLAIN = '#e7e5d8'
SEA = '#dbeafe'

class Map:
    def __init__(s, lon0, lon1, lat0, lat1, k):
        s.lon0, s.lat0, s.k = lon0, lat0, k
        s.W = round((lon1 - lon0) * k); s.H = round((lat0 - lat1) * k)
    def xy(s, lon, lat): return ((lon - s.lon0) * s.k, (s.lat0 - lat) * s.k)
    def lands(s, colored, tw=False):
        out = []
        for key, (c, pts) in L.items():
            fill = COL[c] if (colored or c == '水') else (SEA if c == '水' else PLAIN)
            if tw and key == 'tw': fill = '#ef4444'
            for sh in (-360, 0, 360):
                xs = [s.xy(lo + sh, la) for lo, la in pts]
                if max(x for x, _ in xs) < 0 or min(x for x, _ in xs) > s.W: continue
                if max(y for _, y in xs) < 0 or min(y for _, y in xs) > s.H: continue
                d = 'M' + 'L'.join(f'{x:.0f} {y:.0f}' for x, y in xs) + 'Z'
                out.append(f'<path d="{d}" fill="{fill}" stroke="#94a3b8" stroke-width="0.8"/>')
        return ''.join(out)
    def text(s, t, lon, lat, size=14, color='#0f172a', anchor='middle', bold=True, italic=False):
        x, y = s.xy(lon, lat)
        st = (' font-style="italic"' if italic else '') + (' font-weight="700"' if bold else '')
        return (f'<text x="{x:.0f}" y="{y:.0f}" font-size="{size}" fill="{color}" text-anchor="{anchor}"'
                f'{st} stroke="#fff" stroke-width="3" paint-order="stroke" stroke-linejoin="round">{t}</text>')
    def pin(s, t, lon, lat, llon=None, llat=None, anchor='start', color='#dc2626', size=13):
        x, y = s.xy(lon, lat); o = f'<circle cx="{x:.0f}" cy="{y:.0f}" r="4.5" fill="{color}" stroke="#fff" stroke-width="1.5"/>'
        if llon is None:
            dx = 7 if anchor == 'start' else (-7 if anchor == 'end' else 0)
            lx, ly = x + dx, y + (4 if anchor != 'middle' else -8)
        else:
            lx, ly = s.xy(llon, llat)
            o = f'<line x1="{x:.0f}" y1="{y:.0f}" x2="{lx:.0f}" y2="{ly - 4:.0f}" stroke="{color}" stroke-width="1"/>' + o
        o += (f'<text x="{lx:.0f}" y="{ly:.0f}" font-size="{size}" font-weight="700" fill="#0f172a" text-anchor="{anchor}"'
              f' stroke="#fff" stroke-width="3" paint-order="stroke" stroke-linejoin="round">{t}</text>')
        return o
    def hline(s, lat, label, color='#64748b', dash='5 4'):
        _, y = s.xy(0, lat)
        return (f'<line x1="0" y1="{y:.0f}" x2="{s.W}" y2="{y:.0f}" stroke="{color}" stroke-width="1.2" stroke-dasharray="{dash}"/>'
                f'<text x="4" y="{y - 4:.0f}" font-size="12" fill="{color}" font-weight="700" stroke="#fff" stroke-width="3" paint-order="stroke">{label}</text>')
    def svg(s, body, label, minw=None):
        mw = f' style="min-width:{minw}px"' if minw else ''
        return (f'<div class="mapwrap"><svg viewBox="0 0 {s.W} {s.H}" width="{s.W}" role="img" aria-label="{label}"{mw}>'
                f'<rect width="{s.W}" height="{s.H}" fill="{SEA}"/>{body}</svg></div>')

